('325', '5', '_news_count', 'field_kc_fp_news_count'),
('326', '5', 'instagram_heading', 'Instagram'),
('327', '5', '_instagram_heading', 'field_kc_fp_instagram_heading'),
('328', '5', 'instagram_lead', '現場の様子や完成したお住まいを日々投稿しています。'),
('329', '5', '_instagram_lead', 'field_kc_fp_instagram_lead'),
('330', '5', 'recruit_heading', '一緒に家をつくる仲間を募集しています'),
('331', '5', '_recruit_heading', 'field_kc_fp_recruit_heading'),
('332', '5', 'recruit_text', '設計・施工管理・大工職。経験者も、これから覚えたい方も歓迎します。'),
('333', '5', '_recruit_text', 'field_kc_fp_recruit_text'),
('334', '5', 'recruit_image', '44'),
('335', '5', '_recruit_image', 'field_kc_recruit_image'),
('336', '5', 'cta_heading', 'まずはお気軽にご相談ください'),
('337', '5', '_cta_heading', 'field_kc_fp_cta_heading'),
('338', '5', 'cta_text', '土地探しの段階でも、リフォームの小さなご相談でも構いません。ご予算の目安だけでもお伝えできます。'),
('339', '5', '_cta_text', 'field_kc_fp_cta_text'),
