INSERT INTO `km_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES 
('356', '5', 'instagram', ''),
('357', '5', '_instagram', 'field_kc_fp_instagram'),
('358', '6', 'services_lead', '設計・施工・アフターまでを自社で担当します。窓口が一つなので、要望と現場のあいだで話がずれません。'),
('359', '6', '_services_lead', 'field_kc_services_lead'),
('360', '6', 'service_1_title', '新築・注文住宅'),
('361', '6', '_service_1_title', 'field_kc_service_1_title'),
('362', '6', 'service_1_catch', '土地の見え方から考える、一邸ずつの設計'),
('363', '6', '_service_1_catch', 'field_kc_service_1_catch'),
('364', '6', 'service_1_image', '46'),
('365', '6', '_service_1_image', 'field_kc_service_1_image'),
('366', '6', 'service_1_description', '同じ間取りでも、土地の向きと周りの建ち方で住み心地は変わります。まず敷地に立ち、光と風の入り方を確認してから図面を引きます。工事費用の目安は、初回のご相談時にお伝えします。'),
('367', '6', '_service_1_description', 'field_kc_service_1_description'),
('368', '6', 'service_1_points', '敷地調査・法規チェック\n間取りのご提案（何度でも）\n資金計画・住宅ローンのご相談\n工事中の現場ご案内\n引き渡し後の定期点検'),
('369', '6', '_service_1_points', 'field_kc_service_1_points'),
('370', '6', 'service_1', ''),
('371', '6', '_service_1', 'field_kc_service_1'),
('372', '6', 'service_2_title', 'リフォーム・リノベーション'),
('373', '6', '_service_2_title', 'field_kc_service_2_title'),
('374', '6', 'service_2_catch', '住みながらでも進められる、暮らしの更新'),
('375', '6', '_service_2_catch', 'field_kc_service_2_catch'),
('376', '6', 'service_2_image', '47'),
('377', '6', '_service_2_image', 'field_kc_service_2_image'),
('378', '6', 'service_2_description', '水回りの入れ替えのような小さな工事から、間取りを変える全面改修まで対応します。既存の構造と断熱の状態を先に確認し、どこまで手を入れると効果が出るかをご説明します。'),
('379', '6', '_service_2_description', 'field_kc_service_2_description'),
('380', '6', 'service_2_points', 'キッチン・浴室・洗面の入れ替え\n間取り変更をともなう改修\n断熱・耐震の補強\nマンションの内装改修\n住みながらの工程調整'),
('381', '6', '_service_2_points', 'field_kc_service_2_points'),
('382', '6', 'service_2', ''),
('383', '6', '_service_2', 'field_kc_service_2'),
('384', '6', 'service_3_title', '外構・エクステリア'),
('385', '6', '_service_3_title', 'field_kc_service_3_title'),
('386', '6', 'service_3_catch', '建物と庭を、ひと続きで考える'),
('387', '6', '_service_3_catch', 'field_kc_service_3_catch'),
('388', '6', 'service_3_image', '48'),
('389', '6', '_service_3_image', 'field_kc_service_3_image'),
('390', '6', 'service_3_description', '駐車場・アプローチ・植栽・目隠しまで、建物の設計と同じ担当が計画します。建物が完成してから外構を別会社に頼むと、高さや素材が合わないことがあります。'),
('391', '6', '_service_3_description', 'field_kc_service_3_description'),
('392', '6', 'service_3_points', '駐車場・土間コンクリート\nアプローチ・門まわり\n植栽・芝張り\nウッドデッキ・テラス\n目隠しフェンス・カーポート'),
('393', '6', '_service_3_points', 'field_kc_service_3_points'),
('394', '6', 'service_3', ''),
('395', '6', '_service_3', 'field_kc_service_3'),
('396', '7', 'company_lead', '姫路を中心に、注文住宅とリノベーションを手がけています。設計から施工まで自社で担当し、引き渡し後の点検も同じ担当者が伺います。'),
('397', '7', '_company_lead', 'field_kc_company_lead'),
('398', '7', 'company_image', '45'),
('399', '7', '_company_image', 'field_kc_company_image'),
('400', '7', 'company_table', '設立,1998年4月\n資本金,2,000万円\n代表者,代表取締役 空野 和真\n従業員数,18名（うち一級建築士2名・二級建築士4名）\n事業内容,注文住宅の設計・施工／リフォーム・リノベーション／外構工事\n加盟団体,兵庫県建築士会（ダミー）'),
('401', '7', '_company_table', 'field_kc_company_table'),
('402', '7', 'company_history', '1998年,姫路市にて創業。木造住宅の新築を中心に事業を開始\n2006年,設計部門を新設。設計から施工までの一貫体制へ\n2014年,リノベーション事業を開始\n2021年,外構・造園部門を新設\n2024年,累計施工 500 棟を達成'),
('403', '7', '_company_history', 'field_kc_company_history'),
('404', '7', 'company_access_note', 'ご来社の際は事前にご連絡ください。駐車場をご用意します。'),
('405', '7', '_company_access_note', 'field_kc_company_access_note');
INSERT INTO `km_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES 
('406', '8', 'recruit_lead', '図面を引く人、現場を回す人、手を動かす人。どの役割も、家が建つまでの同じ一本の流れの上にあります。'),
('407', '8', '_recruit_lead', 'field_kc_recruit_lead'),
('408', '8', 'recruit_image', '44'),
('409', '8', '_recruit_image', 'field_kc_recruit_image'),
('410', '8', 'recruit_message', '当社は年間 20 棟ほどの規模で、一人が一邸に長く関わります。分業で流していく作り方ではないぶん覚えることは多いですが、引き渡しの日に立ち会えます。\n未経験の方は、まず現場の補助から始めていただきます。資格取得の費用は会社が負担します。'),
('411', '8', '_recruit_message', 'field_kc_recruit_message'),
('412', '8', 'recruit_table', '募集職種,設計・施工管理・大工職\n雇用形態,正社員（試用期間3か月）\n勤務地,兵庫県姫路市ソラノワ町0-0-0（本社）\n勤務時間,8:00〜17:00（休憩60分）\n休日休暇,水曜・第2/第4火曜・夏季・年末年始・有給休暇\n給与,月給 22万円〜38万円（経験・資格を考慮）\n諸手当,通勤手当・資格手当・住宅手当・家族手当\n待遇,社会保険完備・資格取得支援・退職金制度\n応募方法,下記フォームよりご応募ください。追ってご連絡します'),
('413', '8', '_recruit_table', 'field_kc_recruit_table'),
('414', '8', 'recruit_form', '[contact-form-7 id=\"676426d\" title=\"採用応募\"]'),
('415', '8', '_recruit_form', 'field_kc_recruit_form'),
('416', '10', 'contact_lead', '土地探しの段階でも、リフォームの小さなご相談でも構いません。内容を確認のうえ、2〜3営業日以内にご返信します。'),
('417', '10', '_contact_lead', 'field_kc_contact_lead'),
('418', '10', 'contact_form', '[contact-form-7 id=\"059c9cd\" title=\"お問い合わせ\"]'),
('419', '10', '_contact_form', 'field_kc_contact_form'),
