INSERT INTO `km_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES 
('5', '0', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', 'ホーム', '', 'publish', 'closed', 'closed', '', 'home', '', '', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', '0', 'https://pacchi.dev/koumuten/home/', '0', 'page', '', '0'),
('6', '0', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', '事業内容', '', 'publish', 'closed', 'closed', '', 'services', '', '', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', '0', 'https://pacchi.dev/koumuten/services/', '0', 'page', '', '0'),
('7', '0', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', '会社概要', '', 'publish', 'closed', 'closed', '', 'company', '', '', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', '0', 'https://pacchi.dev/koumuten/company/', '0', 'page', '', '0'),
('8', '0', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', '採用情報', '', 'publish', 'closed', 'closed', '', 'recruit', '', '', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', '0', 'https://pacchi.dev/koumuten/recruit/', '0', 'page', '', '0'),
('9', '0', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', 'お知らせ', '', 'publish', 'closed', 'closed', '', 'news', '', '', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', '0', 'https://pacchi.dev/koumuten/news/', '0', 'page', '', '0'),
('10', '0', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', 'お問い合わせ', '', 'publish', 'closed', 'closed', '', 'contact', '', '', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', '0', 'https://pacchi.dev/koumuten/contact/', '0', 'page', '', '0'),
('11', '0', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '<h2>個人情報の取り扱いについて</h2>\n<p>当社は、お客様からお預かりした個人情報を適切に管理し、以下の目的の範囲内で利用します。</p>\n<ul><li>お問い合わせへの回答および資料の送付</li><li>ご依頼いただいた工事の見積・設計・施工およびアフターサービス</li><li>採用選考に関するご連絡</li></ul>\n<h2>第三者への提供</h2>\n<p>法令に基づく場合を除き、ご本人の同意なく第三者へ提供することはありません。</p>\n<h2>開示・訂正・削除</h2>\n<p>ご本人からの開示・訂正・削除のご請求には、速やかに対応します。</p>\n<h2>お問い合わせ窓口</h2>\n<p>本ポリシーに関するお問い合わせは、お問い合わせフォームよりご連絡ください。</p>\n<p><small>本サイトは架空の企業を想定した制作サンプルであり、記載の内容は実在の事業者のものではありません。</small></p>', 'プライバシーポリシー', '', 'publish', 'closed', 'closed', '', 'privacy', '', '', '2026-09-06 17:39:59', '2026-09-06 08:39:59', '', '0', 'https://pacchi.dev/koumuten/privacy/', '0', 'page', '', '0'),
('24', '0', '2024-03-15 10:00:00', '2024-03-15 01:00:00', '南に大きく開いた LDK と、来客用にも使える和室を並べました。西日が入る時間帯が長い敷地だったため、開口部を南と東に寄せ、西面はほぼ閉じています。\n\n施主の要望は「掃除がしやすいこと」でした。造作は最小限にとどめ、可動棚と収納の位置だけを生活動線に合わせて決めています。', '余白の多い家', '', 'publish', 'closed', 'closed', '', 'himeji-yoyu-house', '', '', '2026-09-06 17:40:04', '2026-09-06 08:40:04', '', '0', 'https://pacchi.dev/koumuten/works/himeji-yoyu-house/', '0', 'work', '', '0'),
('25', '0', '2026-09-06 16:48:06', '2026-09-06 07:48:06', '', 'work-01', '', 'inherit', 'closed', 'closed', '', 'work-01', '', '', '2026-09-06 16:48:06', '2026-09-06 07:48:06', '', '24', 'https://pacchi.dev/koumuten/works/himeji-yoyu-house/work-01/', '0', 'attachment', 'image/jpeg', '0'),
('26', '0', '2023-11-15 10:00:00', '2023-11-15 01:00:00', '将来の身体の変化を見込んで、段差のない平屋にしています。廊下をつくらず、LDK を中心に各室へ直接入る配置です。\n\n外壁は白の塗り壁。汚れの目立ちやすさを心配されていたため、地面からの跳ね返りがかかる腰から下だけ仕上げを変えています。', '白い箱の平屋', '', 'publish', 'closed', 'closed', '', 'himeji-shiroi-hiraya', '', '', '2026-09-06 17:40:04', '2026-09-06 08:40:04', '', '0', 'https://pacchi.dev/koumuten/works/himeji-shiroi-hiraya/', '0', 'work', '', '0'),
('27', '0', '2026-09-06 16:48:10', '2026-09-06 07:48:10', '', 'work-02', '', 'inherit', 'closed', 'closed', '', 'work-02', '', '', '2026-09-06 16:48:10', '2026-09-06 07:48:10', '', '26', 'https://pacchi.dev/koumuten/works/himeji-shiroi-hiraya/work-02/', '0', 'attachment', 'image/jpeg', '0'),
('28', '0', '2024-06-15 10:00:00', '2024-06-15 01:00:00', '壁付けだったキッチンを対面に変え、隣接していた納戸をパントリーに作り替えました。既存の梁を隠さず現しにしています。\n\n住みながらの工事だったため、水回りが使えない期間を 3 日に収める工程を組みました。', 'キッチンからはじめた改修', '', 'publish', 'closed', 'closed', '', 'kakogawa-kitchen-renovation', '', '', '2026-09-06 17:40:04', '2026-09-06 08:40:04', '', '0', 'https://pacchi.dev/koumuten/works/kakogawa-kitchen-renovation/', '0', 'work', '', '0'),
('29', '0', '2026-09-06 16:48:15', '2026-09-06 07:48:15', '', 'work-03', '', 'inherit', 'closed', 'closed', '', 'work-03', '', '', '2026-09-06 16:48:15', '2026-09-06 07:48:15', '', '28', 'https://pacchi.dev/koumuten/works/kakogawa-kitchen-renovation/work-03/', '0', 'attachment', 'image/jpeg', '0'),
('30', '0', '2024-01-15 10:00:00', '2024-01-15 01:00:00', '3LDK を 1LDK に減らし、そのぶん一室ごとを広くとりました。仕切りを減らすと冷暖房の効きが落ちるため、断熱を先に補強しています。\n\n在宅勤務の時間が長いとのことで、通風と採光を優先して書斎を東側に配置しました。', '余分を抜いた住まい', '', 'publish', 'closed', 'closed', '', 'himeji-minimal-renovation', '', '', '2026-09-06 17:40:04', '2026-09-06 08:40:04', '', '0', 'https://pacchi.dev/koumuten/works/himeji-minimal-renovation/', '0', 'work', '', '0'),
('31', '0', '2026-09-06 16:48:19', '2026-09-06 07:48:19', '', 'work-04', '', 'inherit', 'closed', 'closed', '', 'work-04', '', '', '2026-09-06 16:48:19', '2026-09-06 07:48:19', '', '30', 'https://pacchi.dev/koumuten/works/himeji-minimal-renovation/work-04/', '0', 'attachment', 'image/jpeg', '0'),
('32', '0', '2023-08-15 10:00:00', '2023-08-15 01:00:00', '同居のために一室を足す計画でしたが、既存部分が暗くなることが分かったため、接続部を吹き抜けにして上から光を落としています。\n\n増築は既存の基礎と構造の確認からはじまります。この物件では基礎の補強を先行しました。', '光を通す増築', '', 'publish', 'closed', 'closed', '', 'takasago-hikari-zoukachiku', '', '', '2026-09-06 17:40:04', '2026-09-06 08:40:04', '', '0', 'https://pacchi.dev/koumuten/works/takasago-hikari-zoukachiku/', '0', 'work', '', '0'),
('33', '0', '2026-09-06 16:48:24', '2026-09-06 07:48:24', '', 'work-05', '', 'inherit', 'closed', 'closed', '', 'work-05', '', '', '2026-09-06 16:48:24', '2026-09-06 07:48:24', '', '32', 'https://pacchi.dev/koumuten/works/takasago-hikari-zoukachiku/work-05/', '0', 'attachment', 'image/jpeg', '0'),
('34', '0', '2024-05-15 10:00:00', '2024-05-15 01:00:00', 'リビングの掃き出し窓と同じ高さでテラスを設け、室内から庭までを一続きに見せています。\n\n道路からの視線が気になるとのことで、目隠しは塀ではなく樹木と縦格子で処理しました。風が抜けるぶん、夏の体感が変わります。', '建物とつながる庭', '', 'publish', 'closed', 'closed', '', 'himeji-terrace-garden', '', '', '2026-09-06 17:40:04', '2026-09-06 08:40:04', '', '0', 'https://pacchi.dev/koumuten/works/himeji-terrace-garden/', '0', 'work', '', '0'),
('35', '0', '2026-09-06 16:48:29', '2026-09-06 07:48:29', '', 'work-06', '', 'inherit', 'closed', 'closed', '', 'work-06', '', '', '2026-09-06 16:48:29', '2026-09-06 07:48:29', '', '34', 'https://pacchi.dev/koumuten/works/himeji-terrace-garden/work-06/', '0', 'attachment', 'image/jpeg', '0'),
('36', '0', '2025-07-28 10:00:00', '2025-07-28 01:00:00', '誠に勝手ながら、下記の期間を夏季休業とさせていただきます。\n\n休業期間: 8月10日（日）〜8月17日（日）\n\n期間中にいただいたお問い合わせへのご返信は、8月18日（月）以降に順次対応いたします。ご不便をおかけしますが、よろしくお願いいたします。', '夏季休業のお知らせ', '', 'publish', 'closed', 'closed', '', 'summer-holiday-2025', '', '', '2026-09-06 17:40:06', '2026-09-06 08:40:06', '', '0', 'https://pacchi.dev/koumuten/summer-holiday-2025/', '0', 'post', '', '0'),
('37', '0', '2025-08-20 09:00:00', '2025-08-20 00:00:00', '姫路市内で完成したお住まいの見学会を開催します。\n\n日時: 9月6日（土）・7日（日） 10:00〜16:00\n場所: 兵庫県姫路市（詳細はご予約時にお伝えします）\n\n完全予約制です。お問い合わせフォームまたはお電話にてご連絡ください。実際に建てられた方の工夫を、間取り図と合わせてご覧いただけます。', '完成見学会を開催します（姫路市・9月6日〜7日）', '', 'publish', 'closed', 'closed', '', 'open-house-himeji-0906', '', '', '2026-09-06 17:40:06', '2026-09-06 08:40:06', '', '0', 'https://pacchi.dev/koumuten/open-house-himeji-0906/', '0', 'post', '', '0'),
('38', '0', '2025-08-05 14:00:00', '2025-08-05 05:00:00', '施工実績のページに、姫路市で竣工したお住まいを追加しました。\n\n南に大きく開いた LDK と、来客用にも使える和室を並べた住まいです。間取り図と物件概要を掲載していますので、あわせてご覧ください。', '施工実績に「余白の多い家」を追加しました', '', 'publish', 'closed', 'closed', '', 'works-updated-2025-08', '', '', '2026-09-06 17:40:06', '2026-09-06 08:40:06', '', '0', 'https://pacchi.dev/koumuten/works-updated-2025-08/', '0', 'post', '', '0'),
('39', '0', '2025-06-10 11:00:00', '2025-06-10 02:00:00', '設計・施工管理職の新卒採用を開始しました。\n\n当社は年間 20 棟ほどの規模で、一人が一邸に長く関わります。実際の現場を見ていただく機会も用意していますので、まずは採用ページのフォームよりご連絡ください。', '2026年度の新卒採用を開始しました', '', 'publish', 'closed', 'closed', '', 'recruit-2026', '', '', '2026-09-06 17:40:06', '2026-09-06 08:40:06', '', '0', 'https://pacchi.dev/koumuten/recruit-2026/', '0', 'post', '', '0'),
('40', '0', '2025-05-15 13:00:00', '2025-05-15 04:00:00', 'お引き渡し後の定期点検について、担当者よりご連絡を差し上げています。\n\n点検は 6 か月・1 年・2 年・5 年・10 年のタイミングで実施しています。ご都合が合わない場合は日程を調整しますので、遠慮なくお申し付けください。', '定期点検のご案内について', '', 'publish', 'closed', 'closed', '', 'aftercare-inspection', '', '', '2026-09-06 17:40:06', '2026-09-06 08:40:06', '', '0', 'https://pacchi.dev/koumuten/aftercare-inspection/', '0', 'post', '', '0'),
('41', '0', '2026-09-06 16:48:39', '2026-09-06 07:48:39', '<label>お名前<span class=\"p-form__required\">必須</span>\n[text* your-name autocomplete:name]</label>\n\n<label>ふりがな\n[text your-kana]</label>\n\n<label>メールアドレス<span class=\"p-form__required\">必須</span>\n[email* your-email autocomplete:email]</label>\n\n<label>電話番号\n[tel your-tel autocomplete:tel]</label>\n\n<label>ご相談の種類\n[select your-subject \"新築・注文住宅\" \"リフォーム・リノベーション\" \"外構・エクステリア\" \"その他\"]</label>\n\n<label>ご相談内容<span class=\"p-form__required\">必須</span>\n[textarea* your-message]</label>\n\n<p class=\"p-form__consent-note\"><a href=\"/privacy/\">プライバシーポリシー</a>をご確認のうえ、同意して送信してください。</p>\n\n[acceptance your-consent] プライバシーポリシーに同意します [/acceptance]\n\n[submit \"送信する\"]\n1\n[_site_title] お問い合わせ（[your-subject]）\n[_site_title] <wordpress@localhost.test>\nadmin@example.test\nサイトのお問い合わせフォームから送信がありました。\n\nお名前　　: [your-name]（[your-kana]）\nメール　　: [your-email]\n電話番号　: [your-tel]\nご相談種類: [your-subject]\n\nご相談内容:\n[your-message]\n\n--\n[_site_title]\n送信元: [_url]\nReply-To: [your-email]\n\n\n\n\n[_site_title] \"[your-subject]\"\n[_site_title] <admin@example.test>\nMessage Body:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\n[your-email]\nReply-To: [_site_admin_email]\n\n0\n0\nありがとうございます。送信が完了しました。\n送信に失敗しました。しばらく時間をおいて、もう一度お試しください。\n入力内容に誤りがあります。確認してもう一度送信してください。\n送信するには、同意が必要です。\n必須項目です。\n文字数が多すぎます。\n文字数が少なすぎます。\n日付の形式が正しくありません。\n指定できる日付より前の日付です。\n指定できる日付より後の日付です。\nファイルのアップロードに失敗しました。\nこのファイル形式は受け付けていません。\nファイルサイズが大きすぎます。\nファイルのアップロード中にエラーが発生しました。\n数値の形式が正しくありません。\n指定できる数値より小さい値です。\n指定できる数値より大きい値です。\n答えが正しくありません。\nメールアドレスの形式が正しくありません。\nURL の形式が正しくありません。\n電話番号の形式が正しくありません。', 'お問い合わせ', '', 'publish', 'closed', 'closed', '', '%e3%81%8a%e5%95%8f%e3%81%84%e5%90%88%e3%82%8f%e3%81%9b', '', '', '2026-09-06 19:34:35', '2026-09-06 10:34:35', '', '0', 'https://pacchi.dev/koumuten/?post_type=wpcf7_contact_form&#038;p=41', '0', 'wpcf7_contact_form', '', '0'),
('42', '0', '2026-09-06 16:48:39', '2026-09-06 07:48:39', '<label>お名前<span class=\"p-form__required\">必須</span>\n[text* your-name autocomplete:name]</label>\n\n<label>ふりがな\n[text your-kana]</label>\n\n<label>メールアドレス<span class=\"p-form__required\">必須</span>\n[email* your-email autocomplete:email]</label>\n\n<label>電話番号<span class=\"p-form__required\">必須</span>\n[tel* your-tel autocomplete:tel]</label>\n\n<label>希望職種<span class=\"p-form__required\">必須</span>\n[select* your-position \"設計\" \"施工管理\" \"大工職\" \"未定・相談したい\"]</label>\n\n<label>経験\n[select your-experience \"経験あり（3年以上）\" \"経験あり（3年未満）\" \"未経験\"]</label>\n\n<label>志望動機・自己PR<span class=\"p-form__required\">必須</span>\n[textarea* your-message]</label>\n\n<p class=\"p-form__consent-note\"><a href=\"/privacy/\">プライバシーポリシー</a>をご確認のうえ、同意して送信してください。</p>\n\n[acceptance your-consent] プライバシーポリシーに同意します [/acceptance]\n\n[submit \"応募する\"]\n1\n[_site_title] 採用応募（[your-position]）\n[_site_title] <wordpress@localhost.test>\nadmin@example.test\n採用応募フォームから送信がありました。\n\nお名前　: [your-name]（[your-kana]）\nメール　: [your-email]\n電話番号: [your-tel]\n希望職種: [your-position]\n経験　　: [your-experience]\n\n志望動機・自己PR:\n[your-message]\n\n--\n[_site_title]\n送信元: [_url]\nReply-To: [your-email]\n\n\n\n\n[_site_title] \"[your-subject]\"\n[_site_title] <admin@example.test>\nMessage Body:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\n[your-email]\nReply-To: [_site_admin_email]\n\n0\n0\nありがとうございます。送信が完了しました。\n送信に失敗しました。しばらく時間をおいて、もう一度お試しください。\n入力内容に誤りがあります。確認してもう一度送信してください。\n送信するには、同意が必要です。\n必須項目です。\n文字数が多すぎます。\n文字数が少なすぎます。\n日付の形式が正しくありません。\n指定できる日付より前の日付です。\n指定できる日付より後の日付です。\nファイルのアップロードに失敗しました。\nこのファイル形式は受け付けていません。\nファイルサイズが大きすぎます。\nファイルのアップロード中にエラーが発生しました。\n数値の形式が正しくありません。\n指定できる数値より小さい値です。\n指定できる数値より大きい値です。\n答えが正しくありません。\nメールアドレスの形式が正しくありません。\nURL の形式が正しくありません。\n電話番号の形式が正しくありません。', '採用応募', '',